# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


class ContactError(ProjectError):
    """A contact sheet cannot be built."""


def _sort_key(student: Student):
    name = student.display_name.casefold()
    return (name, student.student_id)


def _cells(student: Student) -> List[str]:
    email = student.email.strip()
    return [student.display_name, student.section, email]


def _require_emails(people: List[Student]) -> None:
    for person in people:
        if not (person.email or "").strip():
            raise ContactError(
                f"no email for {person.display_name}"
                f" ({person.student_id})"
            )


def _column_widths(people: List[Student]) -> List[int]:
    columns = zip(*(_cells(person) for person in people))
    return [
        max(len(cell) for cell in column)
        for column in columns
    ]


def _format_row(person: Student, widths: List[int]) -> str:
    cells = _cells(person)
    pairs = zip(cells, widths)
    padded = [cell.ljust(width) for cell, width in pairs]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Name, section and email rows, sorted by name."""
    people = sorted(students, key=_sort_key)
    if not people:
        raise ContactError("no students to list")
    _require_emails(people)
    widths = _column_widths(people)
    return [
        _format_row(person, widths) for person in people
    ]
